import http from 'k6/http';
import { check } from 'k6';

export const options = {
  vus: 2,
  iterations: 2,
};

export default function () {
  const baseUrl = __ENV.BASE_URL;
  const jsonHeaders = { 'Content-Type': 'application/json' };

  // 1. Login to get session cookie and CSRF token
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: jsonHeaders }
  );

  check(loginRes, {
    'login status is 200': (r) => r.status === 200,
  });

  const csrfToken = loginRes.json('csrf');

  // 2. GET /products (required before cart)
  const productsRes = http.get(`${baseUrl}/products`);

  check(productsRes, {
    'products status is 200': (r) => r.status === 200,
  });

  // 3. POST /cart with CSRF token
  const cartHeaders = Object.assign({}, jsonHeaders, {
    'X-CSRF-Token': csrfToken,
  });

  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    { headers: cartHeaders }
  );

  check(cartRes, {
    'cart status is 200': (r) => r.status === 200,
  });

  // 4. POST /checkout with CSRF token
  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    { headers: cartHeaders }
  );

  check(checkoutRes, {
    'checkout status is 200': (r) => r.status === 200,
  });
}
